#pragma once
#include "kstationProgramStateTask.h"
#include "kstationNativePatchUnpack.h"
#include "kstationNativeDspTransfer.h"
#include <variant>
namespace kstation {
class NativeProgramState final {
 using I=ProgramIndexTask;using A=ProgramAddressTask;using C=ProgramCopyTask;using L=ProgramLoadTask;using M=ProgramMirrorClearTask;using O=ProgramModeTask;using D=ProgramDspResetTask;
 struct Job {std::variant<I,A,C,L,M,O,D>task;uint32_t child=0;};
public:
 struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,5>CodeRanges{{{0x4c36,0x4c4a},{0x4ca0,0x4d10},{0x563a,0x5650},{0x8218,0x823c},{0x833a,0x834a}}};
 bool active()const{return depth_||unpack_.active()||dsp_.active();}void reset(){depth_=0;unpack_.reset();dsp_.reset();lastIndex_=0;steps_=0;}uint64_t steps()const{return steps_;}
 uint32_t requestedChild()const{return depth_&&waiting(jobs_[depth_-1])?jobs_[depth_-1].child:0;}
 static bool candidate(uint32_t at){for(auto r:CodeRanges)if(at>=r.begin&&at<r.end)return true;return false;}
 bool step(Stage1Cpu&c){if(c.interruptMode2||c.pending_irqs_high||(c.pending_irqs&&!(c.ccr&128)))return false;auto at=uint32_t(c.getPC());if(NativePatchUnpack::candidate(at)){if(!unpack_.step(c))return false;++steps_;return true;}if(NativeDspTransfer::candidate(at)){if(!dsp_.step(c))return false;++steps_;return true;}
  if(!depth_||boundary(jobs_[depth_-1])!=at){Job j;if(at==0x4c36)j.task.emplace<I>(uint32_t(c.reg32(0)));else if(at==0x4cb8)j.task.emplace<A>();else if(at==0x4ce4)j.task.emplace<C>(uint32_t(c.reg32(0)));else if(at==0x4ca0)j.task.emplace<L>();else if(at==0x563a)j.task.emplace<M>();else if(at==0x8218)j.task.emplace<O>();else if(at==0x833a)j.task.emplace<D>();else return false;if(depth_==jobs_.size())throw std::logic_error("Native K program child capacity");jobs_[depth_++]=j;}
  auto&j=jobs_[depth_-1];resume(j);if(at!=boundary(j))throw std::logic_error("Native K program boundary differs");if(c.pending_irqs)c.read8(0xfffff2);auto len=bytes(j);auto cr=credits(j,c,len);auto cost=std::visit([&](const auto&t){return t.nextClocks(cr);},j.task);auto begin=c.cycles;c.fetchClocks(len);c.pc=c.makepc(at+1);project(j,c);
  std::visit([&](auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,I>)t.advanceBefore(cost,cr,[&](bool program)->unsigned{auto reg=program?8:9;c.reg8(reg)=c.read8(int(t.source()+(program?1:0)));if(!program){++c.reg32(0);c.clockI(2);}val(c,c.reg8(reg));return uint8_t(c.reg8(reg));});else if constexpr(std::is_same_v<T,A>)t.advanceBefore(cost,cr,[&]{c.reg8(9)=c.read8(0xcd77);val(c,c.reg8(9));return uint8_t(c.reg8(9));});else if constexpr(std::is_same_v<T,C>)t.advanceBefore(cost,cr,[&](unsigned index){c.reg8(10)=c.read8(int(t.source()+index));++c.reg32(0);val(c,c.reg8(10));c.clockI(2);return uint8_t(c.reg8(10));},[&](unsigned index,uint8_t value){c.write8(int8_t(value),int(0xba5c+index));val(c,c.reg8(10));});else if constexpr(std::is_same_v<T,L>)t.advanceBefore(cost,cr,[&](uint8_t v){val(c,c.reg8(14));c.write8(int8_t(v),0xcc02);});else if constexpr(std::is_same_v<T,M>)t.advanceBefore(cost,cr,[&](unsigned index,uint8_t v){c.write8(int8_t(v),int(0xcf36+index));val(c,c.reg8(9));});else if constexpr(std::is_same_v<T,O>)t.advanceBefore(cost,cr,[&]{c.reg8(14)=c.read8(0xbb23);val(c,c.reg8(14));return uint8_t(c.reg8(14));},[&](uint8_t v){val(c,c.reg8(14));c.write8(int8_t(v),0xd0ee);});else t.advanceBefore(cost,cr);},j.task);
  if(c.cycles-begin!=cost)throw std::logic_error("Native K program clocks differ");auto done=std::visit([](const auto&t){return t.complete();},j.task);if(done){if(auto*t=std::get_if<I>(&j.task))lastIndex_=t->result();--depth_;}else if(!waiting(j))c.pc=c.makepc(boundary(j));++steps_;return true;
 }
private:
 static void val(Stage1Cpu&c,int v){midi_projection::val(c,v);}static void pop(Stage1Cpu&c,unsigned r,bool word){if(word)c.reg16(r)=int16_t(c.read16(int(c.getSP())));else c.reg32(r)=int32_t(c.read32(int(c.getSP())));c.setSP(c.getSP()+(word?2:4));val(c,word?c.reg16(r):c.reg32(r));c.clockI(2);}static void push(Stage1Cpu&c,unsigned r,bool word){c.setSP(c.getSP()-(word?2:4));if(word)c.write16(c.reg16(r),int(c.getSP()));else c.write32(c.reg32(r),int(c.getSP()));val(c,word?c.reg16(r):c.reg32(r));c.clockI(2);}
 static void dec(Stage1Cpu&c,unsigned r,bool byte){int old=byte?c.reg8(r):c.reg16(r),v=old-1;val(c,v);if((old&~v)&(byte?0x80:0x8000))c.ccr|=2;if(byte)c.reg8(r)=int8_t(v);else c.reg16(r)=int16_t(v);}
 static void incLong(Stage1Cpu&c,unsigned r){auto old=uint32_t(c.reg32(r)),v=old+1;c.reg32(r)=int32_t(v);val(c,c.reg32(r));if((~old&v)&0x80000000)c.ccr|=2;}
 static void dispatch(Job&j,Stage1Cpu&c,unsigned target,unsigned returned,bool wide=true){j.child=target;midi_projection::call(c,target,returned,wide);}
 static bool waiting(const Job&j){return std::visit([](const auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,A>||std::is_same_v<T,C>||std::is_same_v<T,L>||std::is_same_v<T,D>)return t.awaiting();else return false;},j.task);}
 void resume(Job&j){if(auto*t=std::get_if<A>(&j.task)){if(t->awaiting())t->resumeChild(lastIndex_);}else std::visit([](auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,C>||std::is_same_v<T,L>||std::is_same_v<T,D>){if(t.awaiting())t.resumeChild();}},j.task);}
 static unsigned boundary(const Job&j){return std::visit([](const auto&t)->unsigned{using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,I>){static constexpr unsigned a[]={0x4c36,0x4c38,0x4c3a,0x4c3c,0x4c3e,0x4c40,0x4c42,0x4c44,0x4c46,0x4c48,0};return a[unsigned(t.stage())];}else if constexpr(std::is_same_v<T,A>){static constexpr unsigned a[]={0x4cb8,0x4cbe,0x4cc2,0x4cc6,0x4cc8,0x4cca,0x4cd0,0x4cd2,0x4cd8,0x4cda,0x4ce0,0x4ce2,0};return a[unsigned(t.stage())];}else if constexpr(std::is_same_v<T,C>){static constexpr unsigned a[]={0x4ce4,0x4cea,0x4cee,0x4cf0,0x4cf2,0x4cf4,0x4cf6,0x4cf8,0x4cfc,0x4d00,0x4d04,0x4d08,0x4d0a,0x4d0e,0};return a[unsigned(t.stage())];}else if constexpr(std::is_same_v<T,L>){static constexpr unsigned a[]={0x4ca0,0x4ca2,0x4ca4,0x4ca8,0x4caa,0x4cae,0x4cb0,0x4cb6,0};return a[unsigned(t.stage())];}else if constexpr(std::is_same_v<T,M>){static constexpr unsigned a[]={0x563a,0x5640,0x5644,0x5646,0x5648,0x564a,0x564c,0x564e,0};return a[unsigned(t.stage())];}else if constexpr(std::is_same_v<T,O>){static constexpr unsigned a[]={0x8218,0x821c,0x8222,0x822a,0x822c,0x822e,0x8230,0x8236,0x823a,0};return a[unsigned(t.stage())];}else{static constexpr unsigned a[]={0x833a,0x833e,0x8344,0x8348,0};return a[unsigned(t.stage())];}},j.task);}
 static unsigned bytes(const Job&j){switch(boundary(j)){case 0x4cb8:case 0x4cd2:case 0x4cda:case 0x4ce4:case 0x563a:case 0x821c:case 0x8230:case 0x833e:case 0x4cca:case 0x4cb0:return 6;case 0x8222:return 8;case 0x8218:case 0x8236:case 0x4cbe:case 0x4cc2:case 0x4cea:case 0x4cf8:case 0x4cfc:case 0x4d00:case 0x4d04:case 0x4d0a:case 0x4ca4:case 0x4caa:case 0x5640:case 0x833a:case 0x8344:return 4;default:return 2;}}
 static unsigned bus(uint32_t at,unsigned n,int last){unsigned cost=0;for(unsigned i=0;i<n;++i){auto a=(at+i)&0xffffff;if(a<0x400000||(a>=0xfffd10&&a<0xffffa0)){if((last&1)||a!=uint32_t(last|1))cost+=a<0x400000?3:1;last=int(a);}else{cost+=a>=0xffffa0?1:3;last=-1;}}return cost;}
 static FlashCredits credits(const Job&j,const Stage1Cpu&c,unsigned len){FlashCredits cr;int history=int(c.getPC()+len-1);cr.pushLong=8+bus(c.getSP()-4,4,c.writeHistory());cr.popLong=8+bus(c.getSP(),4,history);cr.pushWord=5+bus(c.getSP()-2,2,c.writeHistory());cr.popWord=5+bus(c.getSP(),2,history);cr.call=8+bus(c.getSP()-4,4,c.writeHistory());cr.shortCall=3+bus(c.getSP()-4,4,c.writeHistory());cr.ret=5+bus(c.getSP(),4,history);if(auto*t=std::get_if<I>(&j.task)){if(t->stage()==I::Stage::ReadBank||t->stage()==I::Stage::ReadProgram)cr.read=bus(t->source()+(t->stage()==I::Stage::ReadProgram),1,history);}else if(auto*t=std::get_if<A>(&j.task)){if(t->stage()==A::Stage::ReadMode)cr.read=bus(0xcd77,1,history);}else if(auto*t=std::get_if<C>(&j.task)){if(t->stage()==C::Stage::Read)cr.read=bus(t->source()+t->index(),1,history);else if(t->stage()==C::Stage::Write)cr.write=bus(0xba5c+t->index(),1,c.writeHistory());}else if(auto*t=std::get_if<M>(&j.task)){if(t->stage()==M::Stage::Write)cr.write=bus(0xcf36+t->index(),1,c.writeHistory());}else if(auto*t=std::get_if<O>(&j.task)){if(t->stage()==O::Stage::Read)cr.read=bus(0xbb23,1,history);else if(t->stage()==O::Stage::Publish)cr.write=bus(0xd0ee,1,c.writeHistory());}else if(auto*t=std::get_if<L>(&j.task)){if(t->stage()==L::Stage::PublishPending)cr.write=bus(0xcc02,1,c.writeHistory());}return cr;}
 static void project(Job&j,Stage1Cpu&c){if(auto*t=std::get_if<I>(&j.task)){using S=I::Stage;switch(t->stage()){case S::Retain:push(c,1,true);break;case S::DecrementBank:dec(c,9,true);break;case S::BindScale:c.reg8(1)=100;val(c,100);break;case S::Multiply:c.reg16(1)=int16_t(uint8_t(c.reg8(1))*uint8_t(c.reg8(9)));c.clockI(12);break;case S::ExtendProgram:c.reg16(0)=uint8_t(c.reg8(8));val(c,c.reg16(0));break;case S::AddBank:c.reg16(0)=int16_t(midi_projection::arithmetic(c,uint16_t(c.reg16(0)),uint16_t(c.reg16(1)),16,false));break;case S::Restore:pop(c,1,true);break;case S::Return:midi_projection::ret(c);break;default:break;}}
  else if(auto*t=std::get_if<A>(&j.task)){using S=A::Stage;switch(t->stage()){case S::BindSelection:c.reg32(0)=0xcd82;val(c,c.reg32(0));break;case S::ReadIndex:dispatch(j,c,0x4c36,0x4cc2);break;case S::BindScale:c.reg16(8)=128;val(c,128);break;case S::Multiply:c.reg32(0)=int32_t(uint16_t(c.reg16(0))*uint16_t(c.reg16(8)));c.clockI(20);break;case S::Retain:push(c,1,true);break;case S::AddNormal:c.reg32(0)=int32_t(midi_projection::arithmetic(c,c.reg32(0),0x226400,32,false));break;case S::AddAlternate:c.reg32(0)=int32_t(midi_projection::arithmetic(c,c.reg32(0),0x220000,32,false));break;case S::Restore:pop(c,1,true);break;case S::Return:midi_projection::ret(c);break;default:break;}}
  else if(auto*t=std::get_if<C>(&j.task)){using S=C::Stage;switch(t->stage()){case S::BindTarget:c.reg32(1)=0xba5c;val(c,c.reg32(1));break;case S::Count:c.reg16(10)=128;val(c,128);break;case S::Advance:incLong(c,1);break;case S::Decrement:dec(c,10,false);break;case S::Invalidate:dispatch(j,c,0x563a,0x4cfc);break;case S::Unpack:dispatch(j,c,0x4f48,0x4d00);break;case S::ResetDsp:dispatch(j,c,0x833a,0x4d04);break;case S::RefreshPanel:dispatch(j,c,0x571e,0x4d08);break;case S::ClearVoice:c.reg8(14)=0;val(c,0);break;case S::InitVoice:dispatch(j,c,0x816c,0x4d0e);break;case S::Return:midi_projection::ret(c);break;default:break;}}
  else if(auto*t=std::get_if<L>(&j.task)){using S=L::Stage;switch(t->stage()){case S::ResolveAddress:dispatch(j,c,0x4cb8,0x4ca2,false);break;case S::Copy:dispatch(j,c,0x4ce4,0x4ca4,false);break;case S::ModeLatch:dispatch(j,c,0x8218,0x4ca8);break;case S::ClearVoice:case S::ClearPending:c.reg8(14)=0;val(c,0);break;case S::ReleaseVoices:dispatch(j,c,0x763e,0x4cae);break;case S::Return:midi_projection::ret(c);break;default:break;}}
  else if(auto*t=std::get_if<M>(&j.task)){using S=M::Stage;switch(t->stage()){case S::Bind:c.reg32(0)=0xcf36;val(c,c.reg32(0));break;case S::Count:c.reg16(9)=205;val(c,205);break;case S::Prepare:c.reg8(9)=-1;val(c,-1);break;case S::Advance:incLong(c,0);break;case S::Decrement:dec(c,9,false);break;case S::Return:midi_projection::ret(c);break;default:break;}}
  else if(auto*t=std::get_if<O>(&j.task)){using S=O::Stage;switch(t->stage()){case S::Retain:push(c,6,false);break;case S::Bind:c.reg32(6)=0xba5c;val(c,c.reg32(6));break;case S::Compare:(void)midi_projection::arithmetic(c,uint8_t(c.reg8(14)),1,8,true);break;case S::Prepare:c.reg8(14)=1;val(c,1);break;case S::Restore:pop(c,6,false);break;case S::Return:midi_projection::ret(c);break;default:break;}}
  else if(auto*t=std::get_if<D>(&j.task)){using S=D::Stage;switch(t->stage()){case S::Address:c.reg16(4)=int16_t(0x802b);val(c,c.reg16(4));break;case S::Word:c.reg32(1)=256;val(c,256);break;case S::Send:dispatch(j,c,0x165e,0x8348);break;case S::Return:midi_projection::ret(c);break;default:break;}}
 }
 std::array<Job,8>jobs_{};unsigned depth_=0;uint16_t lastIndex_=0;uint64_t steps_=0;NativePatchUnpack unpack_;NativeDspTransfer dsp_;
};
}
